def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    zeros = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    twos = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not zeros:
        return out

    r0, r1 = min(r for r, c in zeros), max(r for r, c in zeros)
    c0, c1 = min(c for r, c in zeros), max(c for r, c in zeros)
    rh, cw = r1 - r0 + 1, c1 - c0 + 1
    start = (r0, c0)
    zero_set = set(zeros)

    def valid(r, c):
        if r < 0 or c < 0 or r + rh > h or c + cw > w:
            return False
        for y in range(r, r + rh):
            for x in range(c, c + cw):
                if grid[y][x] not in (1, 2) and (y, x) not in zero_set:
                    return False
        return True

    # The zero rectangle travels through placements that fit in the 1-region.
    queue = [start]
    dist = {start: 0}
    for r, c in queue:
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nxt = (r + dr, c + dc)
            if nxt not in dist and valid(*nxt):
                dist[nxt] = dist[(r, c)] + 1
                queue.append(nxt)

    target = None
    if twos:
        tr0, tr1 = min(r for r, c in twos), max(r for r, c in twos)
        tc0, tc1 = min(c for r, c in twos), max(c for r, c in twos)
        if tr1 - tr0 + 1 == rh and tc1 - tc0 + 1 == cw:
            if (tr0, tc0) in dist:
                target = (tr0, tc0)

    if target is not None:
        dest = target
    else:
        # Stop at the farthest reachable placement.
        dest = max(dist, key=lambda p: (dist[p], p[0], p[1]))

    for r, c in zeros:
        out[r][c] = 1
    for r in range(dest[0], dest[0] + rh):
        for c in range(dest[1], dest[1] + cw):
            out[r][c] = 0
    return out
